```java
package example;

import java.math.BigDecimal;

import org.babyfish.jimmer.Page;
import org.babyfish.jimmer.sql.JSqlClient;
import org.babyfish.jimmer.sql.ast.mutation.SaveMode;

import example.dto.BookView;

public final class CanaryJava {

    private CanaryJava() {}

    /** Strict create: INSERT_ONLY never upserts; a duplicate @Key name fails. */
    public static BookView create(JSqlClient sql, String name, BigDecimal price, String tenantId) {
        return sql.saveCommand(
                Immutables.createBook(draft -> {
                    draft.setName(name);
                    draft.setPrice(price);
                    draft.setTenantId(tenantId);
                })
        )
        .setMode(SaveMode.INSERT_ONLY)
        .execute(BookView.class)
        .getModifiedView();
    }

    /** Optional name filter; stable order (name, id); exact total via fetchPage. */
    public static Page<BookView> search(JSqlClient sql, String name, int page, int size) {
        var table = Tables.BOOK_TABLE;
        return sql.createQuery(table)
                .where(table.name().likeIf(name))
                .orderBy(table.name().asc(), table.id().asc())
                .select(table.fetch(BookView.class))
                .fetchPage(page, size);
    }
}
```

**Can a teammate call `result.isAccepted()`?** No. `isAccepted`/`getIsAccepted` does not exist in 0.9.111 on Java `SimpleSaveResult` (nor Kotlin `KSimpleSaveResult`); that acceptance protocol is newer and will not compile here. On this release use the thrown exception from `INSERT_ONLY` for strict-create success and `getModifiedEntity()`/`getModifiedView()`, `isModified()`, `getAffectedRowCount(Book.class)` for inspection — remembering `isModified` is not a persistence-success flag.

